import styled from '@emotion/styled';

export const StyledBeerEvolutionContent = styled.div({
  display: 'flex',
  flexDirection: 'column',
  width: '100%',
  boxSizing: 'border-box',
});

export const StyledBeerEvolutionInnerCard = styled.div<{ $loading?: boolean }>(
  ({ $loading }) => ({
    display: 'flex',
    flexDirection: 'column',
    borderRadius: '16px',
    overflow: 'hidden',
    border: '1px solid rgba(20, 20, 20, 0.12)',
    paddingBottom: '16px',
    backgroundColor: '#FFFFFF',
    width: '100%',
    boxSizing: 'border-box',

    ...($loading === true && {
      paddingBottom: '0',
    }),
  }),
);

export const StyledWaterfallContainer = styled.div({
  width: '100%',
  height: '140px',
  borderBottom: '1px solid rgba(20, 20, 20, 0.12)',
});

export const StyledAvatarContainer = styled.div({
  alignItems: 'center',
  paddingLeft: '20px',
  paddingRight: '16px',
  marginBottom: '15px',
});
